class Solution {
public:
    vector<int> findPermutation(string s) {
        int n = static_cast<int>(s.size());
        vector<int> result(n + 1);
        iota(result.begin(), result.end(), 1);
        for (int i = 0; i < n;) {
            if (s[i] != 'D') {
                ++i;
                continue;
            }
            int j = i;
            while (j < n && s[j] == 'D') {
                ++j;
            }
            reverse(result.begin() + i, result.begin() + j + 1);
            i = j;
        }
        return result;
    }
};
